1	// Meeting-room booking server: JSON API, static page, one JSON data file.
2	// Only Node.js built-ins. Request handling after the body is read is fully
3	// synchronous (including the save), so requests are handled one at a time.
4	import http from 'node:http';
5	import fs from 'node:fs';
6	import path from 'node:path';
7	
8	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
9	const MAX_BODY = 10000;
10	const JSON_TYPE = 'application/json; charset=utf-8';
11	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
12	const BOOKINGS_PREFIX = '/api/bookings/';
13	const STATIC_FILES = Object.freeze({
14	  '/': { url: new URL('./public/index.html', import.meta.url), type: 'text/html; charset=utf-8' },
15	  '/app.js': { url: new URL('./public/app.js', import.meta.url), type: 'text/javascript; charset=utf-8' },
16	});
17	
18	class HttpError extends Error {
19	  constructor(status, message) {
20	    super(message);
21	    this.status = status;
22	  }
23	}
24	
25	// ---------- validation helpers ----------
26	
27	const isString = (v) => typeof v === 'string';
28	
29	function isValidDate(value) {
30	  if (!isString(value) || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
31	  const year = Number(value.slice(0, 4));
32	  const month = Number(value.slice(5, 7));
33	  const day = Number(value.slice(8, 10));
34	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
35	  const daysInMonth = [31, year % 4 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
36	  return day <= daysInMonth[month - 1];
37	}
38	
39	const isValidTime = (value) => isString(value) && /^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(value);
40	
41	const isValidTitle = (value) => isString(value) && value.trim().length >= 1 && value.trim().length <= 80;
42	
43	const overlaps = (a, b) => a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
44	
45	const ownValue = (obj, key) => (Object.hasOwn(obj, key) ? obj[key] : undefined);
46	
47	function isPlainObject(value) {
48	  return typeof value === 'object' && value !== null && !Array.isArray(value);
49	}
50	
51	function hasExactKeys(obj, keys) {
52	  const own = Object.keys(obj);
53	  return own.length === keys.length && keys.every((k) => Object.hasOwn(obj, k));
54	}
55	
56	// ---------- data file ----------
57	
58	function isStoredBooking(b, nextId) {
59	  return isPlainObject(b) && hasExactKeys(b, BOOKING_KEYS)
60	    && Number.isSafeInteger(b.id) && b.id >= 1 && b.id < nextId
61	    && ROOMS.includes(b.room) && isValidTitle(b.title) && b.title === b.title.trim()
62	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.start < b.end;
63	}
64	
65	function isValidState(data) {
66	  if (!isPlainObject(data) || !hasExactKeys(data, ['nextId', 'bookings'])) return false;
67	  const { nextId, bookings } = data;
68	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
69	  if (!bookings.every((b) => isStoredBooking(b, nextId))) return false;
70	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return false;
71	  return bookings.every((b, i) => bookings.every((o, j) => i === j || !overlaps(b, o)));
72	}
73	
74	/** Returns the loaded state, or null when the file cannot be used. */
75	function loadState(filePath) {
76	  let text;
77	  try {
78	    text = fs.readFileSync(filePath, 'utf8');
79	  } catch (err) {
80	    if (err && err.code === 'ENOENT') return { nextId: 1, bookings: [] };
81	    return null;
82	  }
83	  try {
84	    const data = JSON.parse(text);
85	    return isValidState(data) ? { nextId: data.nextId, bookings: data.bookings } : null;
86	  } catch {
87	    return null;
88	  }
89	}
90	
91	// Writes the file without creating folders; throws on failure.
92	function saveState(filePath, state) {
93	  fs.writeFileSync(filePath, JSON.stringify(state));
94	}
95	
96	// ---------- routing ----------
97	
98	function splitTarget(target) {
99	  const q = target.indexOf('?');
100	  return q === -1 ? { path: target, query: null } : { path: target.slice(0, q), query: target.slice(q + 1) };
101	}
102	
103	/** Returns { handler, params } or throws HttpError 404/405. */
104	function route(method, pathname, routes) {
105	  if (Object.hasOwn(routes, pathname)) {
106	    const handler = routes[pathname][method];
107	    if (!handler) throw new HttpError(405, 'method not allowed');
108	    return { handler, id: null };
109	  }
110	  if (pathname.startsWith(BOOKINGS_PREFIX)) {
111	    const id = pathname.slice(BOOKINGS_PREFIX.length);
112	    if (id.length > 0 && !id.includes('/')) {
113	      if (method !== 'DELETE') throw new HttpError(405, 'method not allowed');
114	      return { handler: 'deleteBooking', id };
115	    }
116	  }
117	  throw new HttpError(404, 'not found');
118	}
119	
120	const ROUTES = Object.freeze({
121	  '/api/rooms': { GET: 'listRooms' },
122	  '/api/bookings': { GET: 'listBookings', POST: 'createBooking' },
123	  '/': { GET: 'static' },
124	  '/app.js': { GET: 'static' },
125	});
126	
127	// ---------- handlers ----------
128	
129	function sortBookings(bookings) {
130	  return [...bookings].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1
131	    : a.start < b.start ? -1 : a.start > b.start ? 1
132	      : ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room)));
133	}
134	
135	function listBookings(state, query) {
136	  const params = new URLSearchParams(query ?? '');
137	  if (!params.has('date')) return { status: 200, body: { bookings: sortBookings(state.bookings) } };
138	  const date = params.get('date');
139	  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
140	  return { status: 200, body: { bookings: sortBookings(state.bookings.filter((b) => b.date === date)) } };
141	}
142	
143	function checkContentType(header) {
144	  const media = isString(header) ? header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '').toLowerCase() : '';
145	  if (media !== 'application/json') throw new HttpError(415, 'content type must be application/json');
146	}
147	
148	function parseBookingInput(body) {
149	  let data;
150	  try {
151	    data = JSON.parse(body.toString('utf8'));
152	  } catch {
153	    throw new HttpError(400, 'body must be a JSON object');
154	  }
155	  if (!isPlainObject(data)) throw new HttpError(400, 'body must be a JSON object');
156	  const [room, title, date, start, end] = ['room', 'title', 'date', 'start', 'end'].map((k) => ownValue(data, k));
157	  if (!isString(room) || !ROOMS.includes(room)) throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
158	  if (!isValidTitle(title)) throw new HttpError(400, 'title must be 1 to 80 characters');
159	  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
160	  if (!isValidTime(start)) throw new HttpError(400, 'start must be HH:MM');
161	  if (!isValidTime(end)) throw new HttpError(400, 'end must be HH:MM');
162	  if (end <= start) throw new HttpError(400, 'end must be after start');
163	  return { room, title: title.trim(), date, start, end };
164	}
165	
166	function createBooking(store, req, body) {
167	  checkContentType(req.headers['content-type']);
168	  if (body.tooLarge) throw new HttpError(413, 'body too large');
169	  const input = parseBookingInput(body.data);
170	  const state = store.state;
171	  const clash = state.bookings.filter((b) => overlaps(b, input))
172	    .reduce((first, b) => (first === null || b.start < first.start ? b : first), null);
173	  if (clash) throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
174	  const booking = { id: state.nextId, ...input };
175	  store.commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
176	  return { status: 201, body: booking };
177	}
178	
179	function deleteBooking(store, id) {
180	  const state = store.state;
181	  const found = /^[1-9][0-9]*$/.test(id) && state.bookings.some((b) => String(b.id) === id);
182	  if (!found) throw new HttpError(404, 'booking not found');
183	  store.commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => String(b.id) !== id) });
184	  return { status: 204, body: null };
185	}
186	
187	// ---------- HTTP plumbing ----------
188	
189	function sendJson(res, status, body) {
190	  if (body === null) {
191	    res.writeHead(status);
192	    res.end();
193	    return;
194	  }
195	  const payload = Buffer.from(JSON.stringify(body), 'utf8');
196	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': payload.length });
197	  res.end(payload);
198	}
199	
200	function sendStatic(res, pathname) {
201	  const file = STATIC_FILES[pathname];
202	  fs.readFile(file.url, (err, data) => {
203	    if (err) {
204	      sendJson(res, 500, { error: 'internal error' });
205	      return;
206	    }
207	    res.writeHead(200, { 'Content-Type': file.type, 'Content-Length': data.length });
208	    res.end(data);
209	  });
210	}
211	
212	// Reads the whole body; keeps at most MAX_BODY bytes and counts every byte received.
213	function readBody(req, onDone) {
214	  const chunks = [];
215	  let received = 0;
216	  req.on('data', (chunk) => {
217	    received += chunk.length;
218	    if (received <= MAX_BODY) chunks.push(chunk);
219	  });
220	  req.on('end', () => onDone({ tooLarge: received > MAX_BODY, data: received > MAX_BODY ? null : Buffer.concat(chunks) }));
221	  req.on('error', () => req.destroy());
222	}
223	
224	function dispatch(store, req, res, body) {
225	  const { path: pathname, query } = splitTarget(req.url);
226	  const { handler, id } = route(req.method, pathname, ROUTES);
227	  switch (handler) {
228	    case 'static': return sendStatic(res, pathname);
229	    case 'listRooms': return sendJson(res, 200, { rooms: [...ROOMS] });
230	    case 'listBookings': return send(res, listBookings(store.state, query));
231	    case 'createBooking': return send(res, createBooking(store, req, body));
232	    case 'deleteBooking': return send(res, deleteBooking(store, id));
233	    default: throw new Error('unknown handler');
234	  }
235	}
236	
237	const send = (res, result) => sendJson(res, result.status, result.body);
238	
239	function handleRequest(store, req, res) {
240	  readBody(req, (body) => {
241	    try {
242	      dispatch(store, req, res, body);
243	    } catch (err) {
244	      const status = err instanceof HttpError ? err.status : 500;
245	      const message = err instanceof HttpError ? err.message : 'internal error';
246	      if (!res.headersSent) sendJson(res, status, { error: message });
247	      else res.destroy();
248	    }
249	  });
250	}
251	
252	/** Holds the in-memory state; commit saves first and only then swaps state. */
253	function createStore(filePath, initial) {
254	  let state = initial;
255	  return {
256	    get state() { return state; },
257	    commit(next) {
258	      saveState(filePath, next);
259	      state = next;
260	    },
261	  };
262	}
263	
264	// ---------- startup ----------
265	
266	function parsePort(raw) {
267	  if (raw === undefined || raw === '') return 3000;
268	  if (!/^[0-9]+$/.test(raw)) return null;
269	  const port = Number(raw);
270	  return port <= 65535 ? port : null;
271	}
272	
273	function main() {
274	  const port = parsePort(process.env.PORT);
275	  if (port === null) {
276	    process.stderr.write(`invalid PORT ${process.env.PORT}\n`);
277	    process.exitCode = 1;
278	    return;
279	  }
280	  const name = process.env.DATA_FILE || 'bookings.json';
281	  const filePath = path.resolve(process.cwd(), name);
282	  const initial = loadState(filePath);
283	  if (initial === null) {
284	    process.stderr.write(`cannot read data file ${name}\n`);
285	    process.exitCode = 1;
286	    return;
287	  }
288	  const store = createStore(filePath, initial);
289	  const server = http.createServer((req, res) => handleRequest(store, req, res));
290	  server.on('error', (err) => {
291	    process.stderr.write(`cannot listen on port ${port}: ${err.code ?? 'error'}\n`);
292	    process.exit(1);
293	  });
294	  server.listen(port, '127.0.0.1', () => {
295	    process.stdout.write(`listening on http://127.0.0.1:${server.address().port}\n`);
296	  });
297	}
298	
299	main();
