1	// Shared helpers for server.test.mjs: process spawning, HTTP clients, cleanup.
2	import { spawn } from 'node:child_process';
3	import fs from 'node:fs';
4	import http from 'node:http';
5	import net from 'node:net';
6	import os from 'node:os';
7	import path from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	
10	export const SERVER_PATH = fileURLToPath(new URL('../server.mjs', import.meta.url));
11	export const PUBLIC_DIR = fileURLToPath(new URL('../public/', import.meta.url));
12	export const JSON_TYPE = 'application/json; charset=utf-8';
13	const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
14	
15	const procs = new Set();
16	const dirs = [];
17	
18	/** Creates a temp dir that cleanupAll() removes. */
19	export function tmpDir() {
20	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'rooms-test-'));
21	  dirs.push(dir);
22	  return dir;
23	}
24	
25	const exited = (proc) => proc.exitCode !== null || proc.signalCode !== null;
26	
27	function waitExit(proc) {
28	  if (exited(proc)) return Promise.resolve();
29	  return new Promise((resolve) => proc.once('exit', resolve));
30	}
31	
32	/** Kills every spawned server and removes every temp dir. */
33	export async function cleanupAll() {
34	  const all = [...procs];
35	  procs.clear();
36	  for (const proc of all) if (!exited(proc)) proc.kill('SIGKILL');
37	  await Promise.all(all.map(waitExit));
38	  for (const dir of dirs.splice(0)) fs.rmSync(dir, { recursive: true, force: true });
39	}
40	
41	function buildEnv(env) {
42	  const merged = { ...process.env, PORT: '0', DATA_FILE: path.join(tmpDir(), 'bookings.json'), ...env };
43	  for (const key of Object.keys(merged)) if (merged[key] === undefined) delete merged[key];
44	  return merged;
45	}
46	
47	function spawnServer({ env = {}, cwd } = {}) {
48	  const options = { env: buildEnv(env), stdio: ['ignore', 'pipe', 'pipe'] };
49	  if (cwd) options.cwd = cwd;
50	  const proc = spawn(process.execPath, [SERVER_PATH], options);
51	  procs.add(proc);
52	  let out = '';
53	  let err = '';
54	  proc.stdout.setEncoding('utf8').on('data', (d) => { out += d; });
55	  proc.stderr.setEncoding('utf8').on('data', (d) => { err += d; });
56	  return { proc, stdout: () => out, stderr: () => err, env: options.env };
57	}
58	
59	/** Spawns the server and resolves once it prints its listening line. */
60	export function startServer(opts = {}) {
61	  const s = spawnServer(opts);
62	  return new Promise((resolve, reject) => {
63	    const timer = setTimeout(() => reject(new Error(`server did not start: ${s.stderr()}`)), 5000);
64	    s.proc.stdout.on('data', () => {
65	      const m = LISTEN_RE.exec(s.stdout());
66	      if (!m) return;
67	      clearTimeout(timer);
68	      resolve({
69	        proc: s.proc,
70	        port: Number(m[1]),
71	        dataFile: s.env.DATA_FILE,
72	        stdout: s.stdout,
73	        stderr: s.stderr,
74	        kill: async () => { s.proc.kill('SIGKILL'); await waitExit(s.proc); },
75	      });
76	    });
77	    s.proc.once('exit', (code) => {
78	      clearTimeout(timer);
79	      reject(new Error(`server exited early (${code}): ${s.stderr()}`));
80	    });
81	  });
82	}
83	
84	/** Spawns the server and resolves with its exit code and output. */
85	export function runToExit(opts = {}) {
86	  const s = spawnServer(opts);
87	  return new Promise((resolve, reject) => {
88	    const timer = setTimeout(() => {
89	      s.proc.kill('SIGKILL');
90	      reject(new Error(`server did not exit: ${s.stdout()}`));
91	    }, 5000);
92	    s.proc.once('exit', (code) => {
93	      clearTimeout(timer);
94	      resolve({ code, stdout: s.stdout(), stderr: s.stderr() });
95	    });
96	  });
97	}
98	
99	function parseJson(text) {
100	  try {
101	    return JSON.parse(text);
102	  } catch {
103	    return undefined; // not JSON: callers see json === undefined
104	  }
105	}
106	
107	/** HTTP request with full control of the path and headers. body may be an array of chunks. */
108	export function request(port, { method = 'GET', path: target = '/', headers = {}, body } = {}) {
109	  return new Promise((resolve, reject) => {
110	    const h = { Connection: 'close', ...headers };
111	    const parts = body === undefined ? [] : Array.isArray(body) ? body : [body];
112	    const chunked = Object.keys(h).some((k) => k.toLowerCase() === 'transfer-encoding');
113	    if (body !== undefined && !chunked) {
114	      h['Content-Length'] = parts.reduce((n, p) => n + Buffer.byteLength(p), 0);
115	    }
116	    const req = http.request({ host: '127.0.0.1', port, method, path: target, headers: h, agent: false }, (res) => {
117	      const chunks = [];
118	      res.on('data', (c) => chunks.push(c));
119	      res.on('error', reject);
120	      res.on('end', () => {
121	        const text = Buffer.concat(chunks).toString('utf8');
122	        resolve({ status: res.statusCode, headers: res.headers, text, json: parseJson(text) });
123	      });
124	    });
125	    req.on('error', reject);
126	    req.setTimeout(5000, () => req.destroy(new Error('request timeout')));
127	    for (const p of parts) req.write(p);
128	    req.end();
129	  });
130	}
131	
132	/** Writes raw bytes to a socket and returns everything the server sends back. */
133	export function rawRequest(port, data) {
134	  return new Promise((resolve, reject) => {
135	    const chunks = [];
136	    const sock = net.connect(port, '127.0.0.1', () => sock.write(data));
137	    sock.setTimeout(5000, () => sock.destroy(new Error('raw request timeout')));
138	    sock.on('data', (c) => chunks.push(c));
139	    sock.on('error', reject);
140	    sock.on('close', () => resolve(Buffer.concat(chunks).toString('utf8')));
141	  });
142	}
143	
144	export function rawGet(port, target, method = 'GET') {
145	  return rawRequest(port, `${method} ${target} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n`);
146	}
147	
148	export function parseRaw(text) {
149	  const split = text.indexOf('\r\n\r\n');
150	  const head = split === -1 ? text : text.slice(0, split);
151	  const body = split === -1 ? '' : text.slice(split + 4);
152	  return { status: Number(head.split(' ')[1]), head, body, json: parseJson(body) };
153	}
154	
155	export function post(port, obj) {
156	  return request(port, {
157	    method: 'POST',
158	    path: '/api/bookings',
159	    headers: { 'Content-Type': 'application/json' },
160	    body: JSON.stringify(obj),
161	  });
162	}
