1	import { afterEach, describe, test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import fs from 'node:fs';
4	import net from 'node:net';
5	import path from 'node:path';
6	import {
7	  JSON_TYPE, PUBLIC_DIR, cleanupAll, parseRaw, post, rawGet, request, runToExit, startServer, tmpDir,
8	} from './helpers.mjs';
9	
10	afterEach(cleanupAll);
11	
12	const VALID = Object.freeze({ room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00' });
13	const book = (over = {}) => ({ ...VALID, ...over });
14	const stored = (id, over = {}) => ({ id, ...book(over) });
15	const state = (nextId, bookings) => JSON.stringify({ nextId, bookings });
16	
17	function expectError(res, status, message, label = '') {
18	  assert.equal(res.status, status, `${label} status (body ${res.text})`);
19	  assert.equal(res.headers['content-type'], JSON_TYPE, `${label} content-type`);
20	  assert.deepEqual(res.json, { error: message }, label);
21	}
22	
23	/** Starts a server on a fresh temp dir; optional seed is written to the data file first. */
24	async function boot(seed, env = {}) {
25	  const dir = tmpDir();
26	  const file = path.join(dir, 'b.json');
27	  if (seed !== undefined) fs.writeFileSync(file, seed);
28	  const server = await startServer({ env: { DATA_FILE: file, ...env } });
29	  return { ...server, dir, file };
30	}
31	
32	const listIds = async (port, query = '') => (await request(port, { path: `/api/bookings${query}` })).json.bookings.map((b) => b.id);
33	
34	// ---------------------------------------------------------------- startup
35	
36	describe('startup: PORT', () => {
37	  for (const value of ['abc', '65536', '-1', '1e3', ' 80', '+80', '80a', '99999999999']) {
38	    test(`PORT=${JSON.stringify(value)} exits 1 with one stderr line`, async () => {
39	      const r = await runToExit({ env: { PORT: value } });
40	      assert.equal(r.code, 1);
41	      assert.match(r.stderr, /^[^\n]+\n$/);
42	      assert.equal(r.stdout, '');
43	    });
44	  }
45	
46	  test('PORT=00 is digits only and binds an OS port', async () => {
47	    const s = await startServer({ env: { PORT: '00' } });
48	    assert.ok(s.port > 0);
49	    assert.equal((await request(s.port, { path: '/api/rooms' })).status, 200);
50	  });
51	
52	  test('PORT is checked before the data file is read', async () => {
53	    const dir = tmpDir();
54	    const r = await runToExit({ env: { PORT: 'abc', DATA_FILE: dir } });
55	    assert.equal(r.code, 1);
56	    assert.doesNotMatch(r.stderr, /^cannot read data file/);
57	    assert.match(r.stderr, /^[^\n]+\n$/);
58	  });
59	
60	  test('port in use exits 1 with empty stdout', async () => {
61	    const blocker = net.createServer();
62	    await new Promise((resolve) => blocker.listen(0, '127.0.0.1', resolve));
63	    try {
